import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create material
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.FrontSide,
    toneMapped: false
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position and transform
  const pos = config.scenePosition;
  mesh.position.set(pos.x, pos.y, pos.z);

  if (pos.rotationXYZ) {
    mesh.rotation.set(pos.rotationXYZ[0], pos.rotationXYZ[1], pos.rotationXYZ[2]);
  }

  if (pos.scaleXYZ) {
    mesh.scale.set(pos.scaleXYZ[0], pos.scaleXYZ[1], pos.scaleXYZ[2]);
  }

  group.add(mesh);

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // No event handlers for this static card
  group.userData.handlers = {};

  return group;
}
